import{_ as t,o as a,c as i,ah as o}from"./chunks/framework.D4KxWb5R.js";const m=JSON.parse('{"title":"Bien démarrer","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"src/guide/getting-started.md"}'),n={name:"guide/getting-started.md"};function r(s,e,l,c,u,d){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="bien-demarrer" tabindex="-1">Bien démarrer <a class="header-anchor" href="#bien-demarrer" aria-label="Permalink to &quot;Bien démarrer&quot;">​</a></h1><p>L&#39;accès à M&#39;City IQ se fait uniquement sur invitation : il n&#39;existe pas d&#39;inscription libre.</p><h2 id="recevoir-son-invitation" tabindex="-1">Recevoir son invitation <a class="header-anchor" href="#recevoir-son-invitation" aria-label="Permalink to &quot;Recevoir son invitation&quot;">​</a></h2><p>L&#39;administrateur général crée votre compte avec votre poste et votre périmètre. Vous recevez alors un e-mail d&#39;invitation, à l&#39;adresse renseignée, avec un <strong>mot de passe temporaire</strong>.</p><ul><li>L&#39;invitation est valable <strong>7 jours</strong> par défaut (durée fixée par M&#39;City dans la <a href="./administration/settings.html">configuration</a>).</li><li>Une invitation expirée n&#39;est jamais renouvelée automatiquement : demandez à l&#39;administrateur général de vous en envoyer une nouvelle.</li><li>Une nouvelle invitation remplace la précédente : l&#39;ancien mot de passe temporaire ne fonctionne plus.</li></ul><h2 id="premiere-connexion" tabindex="-1">Première connexion <a class="header-anchor" href="#premiere-connexion" aria-label="Permalink to &quot;Première connexion&quot;">​</a></h2><ol><li>Ouvrez la page de connexion de M&#39;City IQ et saisissez votre adresse e-mail et le mot de passe temporaire.</li><li>Si la double authentification vous est demandée, saisissez le code reçu par e-mail (voir ci-dessous).</li><li>L&#39;écran <strong>Choisissez votre mot de passe</strong> s&#39;affiche : choisissez le vôtre. Il doit compter au moins <strong>12 caractères</strong> par défaut.</li><li>Vous arrivez sur <a href="./desk.html">votre bureau</a>.</li></ol><p>Tant que ce mot de passe n&#39;est pas choisi, le reste de la plateforme reste inaccessible.</p><h2 id="se-connecter" tabindex="-1">Se connecter <a class="header-anchor" href="#se-connecter" aria-label="Permalink to &quot;Se connecter&quot;">​</a></h2><p>Saisissez votre e-mail et votre mot de passe, puis <strong>Se connecter</strong>. Cochez <strong>Se souvenir de moi</strong> pour rester connecté sur ce navigateur.</p><p>Si vous avez enregistré une clé d&#39;accès (passkey), utilisez <strong>Se connecter avec une clé d&#39;accès</strong> : aucun mot de passe ni code ne vous est demandé.</p><p>Après <strong>30 minutes</strong> sans activité (durée réglable par M&#39;City), vous êtes déconnecté de l&#39;intranet et du back-office.</p><h2 id="double-authentification" tabindex="-1">Double authentification <a class="header-anchor" href="#double-authentification" aria-label="Permalink to &quot;Double authentification&quot;">​</a></h2><p>La double authentification peut être exigée pour votre compte ou pour tous les comptes. Elle est alors demandée à chaque connexion, de l&#39;une de ces façons :</p><table tabindex="0"><thead><tr><th>Votre compte a…</th><th>Ce qui vous est demandé</th></tr></thead><tbody><tr><td>Une clé d&#39;accès (passkey)</td><td>Rien de plus : la clé compte pour les deux facteurs.</td></tr><tr><td>Une application d&#39;authentification</td><td>Le code à 6 chiffres de l&#39;application, ou un code de récupération.</td></tr><tr><td>Ni l&#39;une ni l&#39;autre</td><td>Un <strong>code de connexion envoyé par e-mail</strong>.</td></tr></tbody></table><h3 id="le-code-par-e-mail" tabindex="-1">Le code par e-mail <a class="header-anchor" href="#le-code-par-e-mail" aria-label="Permalink to &quot;Le code par e-mail&quot;">​</a></h3><p>L&#39;écran <strong>Vérifiez vos e-mails</strong> vous indique l&#39;adresse où le code est parti.</p><ul><li>Le code compte <strong>6 chiffres</strong> et vaut <strong>15 minutes</strong>.</li><li>Vous avez <strong>5 essais</strong> ; un code ne sert qu&#39;une fois.</li><li><strong>Envoyer un nouveau code</strong> en renvoie un, au plus une fois par minute.</li><li>Cochez <strong>Se souvenir de cet appareil pendant 30 jours</strong> : ce navigateur ne vous demandera plus de code pendant 30 jours. Vous retrouvez ces appareils dans <a href="./account.html#appareils-memorises">Mon compte → Sécurité</a>.</li></ul><p>Pas de code reçu ? Vérifiez vos courriers indésirables, puis renvoyez-en un.</p><p>L&#39;application d&#39;authentification et les clés d&#39;accès restent facultatives ; vous les ajoutez dans <a href="./account.html#securite">Mon compte → Sécurité</a>.</p><h2 id="mot-de-passe-oublie" tabindex="-1">Mot de passe oublié <a class="header-anchor" href="#mot-de-passe-oublie" aria-label="Permalink to &quot;Mot de passe oublié&quot;">​</a></h2><ol><li>Sur la page de connexion, cliquez sur <strong>Mot de passe oublié ?</strong>.</li><li>Saisissez votre e-mail, puis <strong>Envoyer le lien de réinitialisation</strong>.</li><li>Ouvrez le lien reçu (valable 60 minutes) et choisissez un nouveau mot de passe.</li></ol><p>Changer ou réinitialiser votre mot de passe oublie tous vos appareils mémorisés.</p><h2 id="compte-desactive" tabindex="-1">Compte désactivé <a class="header-anchor" href="#compte-desactive" aria-label="Permalink to &quot;Compte désactivé&quot;">​</a></h2><p>Un compte désactivé (départ de M&#39;City) ne peut plus se connecter, ni à M&#39;City IQ ni aux back-offices produits. Il n&#39;est jamais supprimé : seul le PDG peut le réactiver.</p>',25)])])}const h=t(n,[["render",r]]);export{m as __pageData,h as default};
